python3 -c 'import sys,json;N=int(sys.argv[1]) if len(sys.argv)>1 else 8;assert 1<=N<=64;P=[2];exec("def prime(i):\n while len(P)<=i:\n  n=P[-1]+1\n  while any(n%d==0 for d in P if d*d<=n):n+=1\n  P.append(n)\n return P[i]\ndef G(a):\n z=1\n for i,x in enumerate(a):z*=prime(i)**(x+1)\n return z\ndef D(z):\n a=[];i=0\n while z>1:\n  p=prime(i);k=0\n  while z%p==0:z//=p;k+=1\n  if not k:raise ValueError(\"invalid code\")\n  a.append(k-1);i+=1\n return a");W=[(i,t) for i in range(3) for t in range(N)];R=lambda a,b:(b[0]==(a[0]+1)%3 and b[1]==a[1]) or (b[0]==a[0] and b[1]==(a[1]+1)%N);F=lambda a:((a[0]+1)%3,a[1]);cycles=[];exec("for t in range(N):\n a=(0,t);c=[a]\n for _ in range(3):a=F(a);c.append(a)\n assert a==c[0]\n cycles.append([G(x) for x in c])");assert all(D(G(x))==list(x) for x in W);print(json.dumps({"model":"APTM-Omega","worlds":3,"local_times":N,"states":len(W),"godel":"prime-powers","reachable_edges":sum(R(a,b) for a in W for b in W),"cycles":[[str(z) for z in c] for c in cycles],"fixed_point_F3":True,"claim":"formal simulation only; no physical time travel or immortality"},separators=(",",":")))'
